function renderShortcuts(){for(const action of ['settings','panel']){const button=document.getElementById('shortcut-'+action);button.textContent=recordingShortcut===action?'请按组合键…':shortcutDraft[action]??'未设置';document.getElementById('clear-shortcut-'+action).disabled=!shortcutDraft[action];const message=document.getElementById('shortcut-'+action+'-message');message.textContent=state?.shortcutUnavailable?.[action]&&shortcutDraft[action]===state?.shortcuts?.[action]?'此组合键已被占用或无法注册。':action==='settings'?'从任何应用打开 Pulse 设置。':'显示或隐藏悬浮栏。'}}
for(const action of ['settings','panel']){document.getElementById('shortcut-'+action).onclick=()=>{recordingShortcut=recordingShortcut===action?null:action;renderShortcuts()};document.getElementById('clear-shortcut-'+action).onclick=()=>{recordingShortcut=null;shortcutDraft[action]=null;renderShortcuts()}}
document.addEventListener('keydown',e=>{if(!recordingShortcut)return;e.preventDefault();e.stopImmediatePropagation();if(e.key==='Escape'&&!e.ctrlKey&&!e.altKey&&!e.shiftKey&&!e.metaKey){recordingShortcut=null;renderShortcuts();return}if((e.key==='Backspace'||e.key==='Delete')&&!e.ctrlKey&&!e.altKey&&!e.shiftKey&&!e.metaKey){shortcutDraft[recordingShortcut]=null;recordingShortcut=null;renderShortcuts();return}const value=pulseShortcuts.capture(e);if(value){shortcutDraft[recordingShortcut]=value;recordingShortcut=null;renderShortcuts()}else if(!['Control','Alt','Shift','Meta'].includes(e.key))document.getElementById('shortcut-'+recordingShortcut).textContent='请加 Ctrl、Alt 或 Windows';},true);
window.addEventListener('blur',()=>{if(recordingShortcut){recordingShortcut=null;renderShortcuts()}});

const statusLabels={operational:'运行正常',degraded:'性能下降',partialOutage:'部分中断',fullOutage:'服务中断',maintenance:'维护中',unrecognised:'未知状态'};
function activateServiceStatus(page){clearTimeout(statusTimer);const generation=++statusGeneration,id=page.startsWith('provider-')?page.slice(9):null,target=id?[...document.querySelectorAll('[data-status-for]')].find(x=>x.dataset.statusFor===id):null;if(!target)return;let hasReading=false;async function update(){if(generation!==statusGeneration||!target.isConnected)return;const refresh=target.querySelector('[data-status-refresh]');if(refresh)refresh.disabled=true;else target.replaceChildren(el('div','setting-row','正在检查服务状态…'));try{const result=await pulse.serviceStatus(id);if(generation!==statusGeneration||!target.isConnected)return;target.replaceChildren();target.dataset.feed=result.feed;target.dataset.host=new URL(result.address).host;for(const component of result.components){const row=el('div','status-component'),header=el('div','status-component-header'),name=el('span',null,component.name),stateText=el('span','status-'+component.state,statusLabels[component.state]??'未知状态');header.append(name,stateText);row.append(header);if(component.days.length){const bars=el('div','status-bars');for(const [index,day] of component.days.entries()){if(index)bars.append(el('span','status-gap'));const bar=el('span','status-bar status-'+(day.state??'nodata'));if(day.color)bar.style.backgroundColor=day.color;const start=new Date(day.date);bar.title=day.hours&&Number.isFinite(+start)?start.toLocaleString()+' – '+new Date(+start+day.hours*3600000).toLocaleTimeString()+' · '+(statusLabels[day.state]??'无数据'):day.date+' · '+(statusLabels[day.state]??'无数据');bars.append(bar)}row.append(bars);const footer=el('div','status-component-footer');footer.append(el('span',null,(component.days[0]?.hours?String(Math.floor(component.days.length*component.days[0].hours/24)):component.days.length>=90?'90':String(component.days.length))+' 天前'),el('span','status-rule'));if(component.uptime!=null)footer.append(el('span',null,Number(component.uptime.toFixed(2))+'% 正常运行时间'),el('span','status-rule'));footer.append(el('span',null,component.days[0]?.hours?'现在':'今天'));row.append(footer)}target.append(row)}const actions=el('div','setting-row'),info=el('div');info.append(el('strong',null,'状态页'),el('small',null,new URL(result.address).host));const buttons=el('div','key-controls'),reload=el('button',null,'刷新'),open=el('button',null,'打开');reload.type=open.type='button';reload.dataset.statusRefresh='';reload.onclick=()=>{clearTimeout(statusTimer);update()};open.onclick=()=>pulse.openServiceStatus(id);buttons.append(reload,open);actions.append(info,buttons);target.append(actions,el('div','status-note','由 '+result.company+' 的状态页报告；打开此页面时及停留期间每五分钟读取。'));hasReading=true}catch(e){if(generation!==statusGeneration||!target.isConnected)return;target.replaceChildren(el('div','setting-row','无法读取状态页：'+e.message));const row=el('div','setting-row'),retry=el('button',null,'刷新'),open=el('button',null,'打开状态页');retry.type=open.type='button';retry.onclick=()=>{clearTimeout(statusTimer);update()};open.onclick=()=>pulse.openServiceStatus(id);row.append(retry,open);target.append(row);hasReading=false}if(generation===statusGeneration)statusTimer=setTimeout(update,300000)}update()}

