pulse.onSpendMonth(month=>{if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))return;showPage('spend');spendModelFocus=null;spendDayPage=0;document.getElementById('spend-agent').value='';const select=document.getElementById('spend-span');let option=[...select.options].find(x=>x.value===month);if(!option){option=el('option',null,month+' 月');option.value=month;select.append(option)}select.value=month;renderSpend(state);pulse.startSpend(false);loadModelPrices()});
